package org.apache.commons.math.fraction;

import java.io.*;
import java.math.*;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.math.MathRuntimeException;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for {@link org.apache.commons.math.fraction.Fraction#hashCode()}.
 */
public class Fraction_hashCode_TriageGen1Test {

    @Test
    public void testHashCode_SimpleFraction() {
        // Fraction(1, 2)
        // hashCode = 37 * (37 * 1 + 2) is wrong logic, based on formula:
        // 37 * (37 * 17 + 1) + 2 if numerator is 1 and denominator is 2? No.
        // Formula: 37 * (37 * 17 + getNumerator()) + getDenominator() is likely a typo in the prompt's provided logic 
        // (usually it's 37 * numerator + denominator), but I must test the code provided.
        // Provided formula: 37 * (37 * 17 + getNumerator()) + getDenominator()

        Fraction fraction = new Fraction(1, 2);
        int expected = 37 * (37 * 17 + 1) + 2;
        Assert.assertEquals("hashCode should match the specific formula provided", expected, fraction.hashCode());
    }

    @Test
    public void testHashCode_DifferentValues() {
        Fraction f1 = new Fraction(1, 2);
        Fraction f2 = new Fraction(2, 3);

        int expected1 = 37 * (37 * 17 + 1) + 2;
        int expected2 = 37 * (37 * 17 + 2) + 3;

        Assert.assertEquals(expected1, f1.hashCode());
        Assert.assertEquals(expected2, f2.hashCode());
        Assert.assertNotEquals("Different fractions should have different hash codes", f1.hashCode(), f2.hashCode());
    }

    @Test
    public void testHashCode_NegativeValues() {
        // Testing with negative numerator
        Fraction fraction = new Fraction(-1, 2);
        int expected = 37 * (37 * 17 + (-1)) + 2;
        Assert.assertEquals(expected, fraction.hashCode());
    }

    @Test
    public void testHashCode_ZeroNumerator() {
        Fraction fraction = new Fraction(0, 5);
        int expected = 37 * (37 * 17 + 0) + 5;
        Assert.assertEquals(expected, fraction.hashCode());
    }

    @Test
    public void testHashCode_ConsistencyWithEquals() {
        // In Java, if f1.equals(f2), then f1.hashCode() must equal f2.hashCode()
        Fraction f1 = new Fraction(1, 2);
        Fraction f2 = new Fraction(1, 2);
        Fraction f3 = new Fraction(2, 4); // Reduced fraction is 1/2

        Assert.assertTrue(f1.equals(f2));
        Assert.assertTrue(f1.equals(f3));
        Assert.assertEquals("Equal fractions must have equal hash codes", f1.hashCode(), f2.hashCode());
        Assert.assertEquals("Equal fractions must have equal hash codes", f1.hashCode(), f3.hashCode());
    }

    @Test
    public void testHashCode_LargeValues() {
        // Testing potential integer overflow behavior as per the formula
        Fraction fraction = new Fraction(Integer.MAX_VALUE, Integer.MAX_VALUE);
        // The formula will definitely overflow, but we test that it is consistent
        int expected = 37 * (37 * 17 + Integer.MAX_VALUE) + Integer.MAX_VALUE;
        Assert.assertEquals(expected, fraction.hashCode());
    }
}
